'use client';

import { stores } from '@/stores';
import {
  STORAGE_CURRENCY,
  convertAmount,
  currencyName,
  currencySymbol,
  formatAmount as formatMoney,
  formatCompactAmount as formatCompactMoney,
  type MoneyFormat,
} from '@/utils/invest_helper';

const storageFormat: MoneyFormat = {
  code: STORAGE_CURRENCY,
  digits: 0,
  symbol: 'FCFA',
};

/** Convertit et formate les montants stockés (XOF) dans la devise de l'investisseur. */
export function useMoney() {
  const user = stores.useUserStore((state) => state.user);
  const rates = stores.useCurrencyStore((state) => state.rates);
  const preferred = (user?.currency || STORAGE_CURRENCY).toUpperCase();
  const rateMap = rates?.rates ?? { [STORAGE_CURRENCY]: 1, USD: 1 };
  const canConvert = Boolean(rateMap[preferred] && rateMap[STORAGE_CURRENCY]);
  const code = canConvert ? preferred : STORAGE_CURRENCY;
  const meta = rates?.currencies.find((item) => item.code === code);
  const digits = meta?.digits ?? (code === 'XOF' || code === 'XAF' ? 0 : 2);
  const format: MoneyFormat = {
    code,
    digits,
    symbol: currencySymbol(code),
  };

  const toDisplay = (storageAmount: number) =>
    convertAmount(storageAmount, STORAGE_CURRENCY, code, rateMap);
  const toStorage = (displayAmount: number) =>
    convertAmount(displayAmount, code, STORAGE_CURRENCY, rateMap);

  return {
    code,
    digits,
    symbol: format.symbol,
    name: currencyName(code),
    ratesReady: Boolean(rates),
    toDisplay,
    toStorage,
    formatAmount: (storageAmount: number) =>
      formatMoney(toDisplay(storageAmount), format),
    formatCompactAmount: (storageAmount: number) =>
      formatCompactMoney(toDisplay(storageAmount), format),
    formatStorageAmount: (storageAmount: number) =>
      formatMoney(storageAmount, storageFormat),
  };
}
